#!/usr/bin/env python3
"""Generate or freshness-check the batch scenario manifests.

Almost every workload starts from one golden template and changes exactly one
field, so each test in a batch fails only on its own workload. The exceptions
are the two CPU workloads, which start from the Guaranteed whole-CPU variant of
the template, and bad-bare-pod and bad-nodeport, which are a Pod and a Service
rather than a mutated Deployment.

See README.md in this directory for how to add a test to a batch.
"""

import argparse
import copy
import json
import re
import sys
from pathlib import Path


SCRIPT_DIR = Path(__file__).resolve().parent
ROOT = SCRIPT_DIR.parents[3]
IMAGE = "nginxinc/nginx-unprivileged:1.27"
SERVICE_ACCOUNT = "scenario-sa"
RUNTIME_CLASS = "certsuite-smoke"
HEADER = "# Generated by batches/generate-manifests.py; do not edit by hand.\n"


# ---------------------------------------------------------------------------
# Golden template


def golden_pod_spec():
    return {
        "serviceAccountName": SERVICE_ACCOUNT,
        "securityContext": {
            "runAsNonRoot": True,
            "runAsUser": 101,
            "fsGroup": 101,
            "seLinuxOptions": {"level": "s0:c123,c456"},
        },
        "containers": [
            {
                "name": "nginx",
                "image": IMAGE,
                "imagePullPolicy": "IfNotPresent",
                "terminationMessagePolicy": "FallbackToLogsOnError",
                "resources": {"requests": {"cpu": "50m", "memory": "64Mi"}},
                "securityContext": {
                    "runAsNonRoot": True,
                    "allowPrivilegeEscalation": False,
                    "readOnlyRootFilesystem": True,
                    "capabilities": {"drop": ["ALL"]},
                },
                "lifecycle": {
                    "postStart": {"exec": {"command": ["/bin/sh", "-c", "true"]}},
                    "preStop": {"exec": {"command": ["/bin/sh", "-c", "sleep 1"]}},
                },
                "volumeMounts": [{"name": "tmp", "mountPath": "/tmp"}],
            }
        ],
        "volumes": [{"name": "tmp", "emptyDir": {}}],
    }


def container(spec):
    return spec["containers"][0]


def exec_probe(period):
    return {"exec": {"command": ["/bin/sh", "-c", "true"]}, "periodSeconds": period}


# Guaranteed QoS with whole CPUs: in scope for cpu-isolation and cpu-pinning.
CPU_PINNED_ANNOTATIONS = {
    "cpu-load-balancing.crio.io": "disable",
    "irq-load-balancing.crio.io": "disable",
}


def cpu_pinned(spec):
    container(spec)["resources"] = {
        "requests": {"cpu": "1", "memory": "128Mi"},
        "limits": {"cpu": "1", "memory": "128Mi"},
    }
    spec["runtimeClassName"] = RUNTIME_CLASS


# ---------------------------------------------------------------------------
# Object builders


def deployment(name, label, spec, replicas=1, annotations=None, extra_labels=None):
    labels = {"app": name, label: "target"}
    template_labels = dict(labels, **(extra_labels or {}))
    metadata = {"labels": template_labels}
    if annotations:
        metadata["annotations"] = annotations
    return {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {"name": name},
        "spec": {
            "replicas": replicas,
            "selector": {"matchLabels": labels},
            "template": {"metadata": metadata, "spec": spec},
        },
    }


def bare_pod(name, label, spec):
    return {
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {"name": name, "labels": {"app": name, label: "target"}},
        "spec": spec,
    }


def service(name, selector_app, service_type="ClusterIP"):
    return {
        "apiVersion": "v1",
        "kind": "Service",
        "metadata": {"name": name},
        "spec": {
            "type": service_type,
            "selector": {"app": selector_app},
            "ports": [{"port": 8080, "targetPort": 8080, "protocol": "TCP"}],
        },
    }


def service_account():
    return {"apiVersion": "v1", "kind": "ServiceAccount", "metadata": {"name": SERVICE_ACCOUNT}}


def pdb(name, min_available=1):
    return {
        "apiVersion": "policy/v1",
        "kind": "PodDisruptionBudget",
        "metadata": {"name": name},
        "spec": {"minAvailable": min_available, "selector": {"matchLabels": {"app": name}}},
    }


def runtime_class():
    return {
        "apiVersion": "node.k8s.io/v1",
        "kind": "RuntimeClass",
        "metadata": {"name": RUNTIME_CLASS},
        "handler": "runc",
    }


# ---------------------------------------------------------------------------
# pod-spec batch: one violation per workload

POD_SPEC_LABEL = "scenario-pod-spec"


def add_capability(cap):
    def mutate(spec):
        container(spec)["securityContext"]["capabilities"]["add"] = [cap]

    return mutate


def set_pod(key, value):
    def mutate(spec):
        spec[key] = value

    return mutate


def set_container(key, value):
    def mutate(spec):
        container(spec)[key] = value

    return mutate


def set_container_security(key, value):
    def mutate(spec):
        container(spec)["securityContext"][key] = value

    return mutate


def drop_container(key):
    def mutate(spec):
        del container(spec)[key]

    return mutate


def drop_lifecycle(hook):
    def mutate(spec):
        del container(spec)["lifecycle"][hook]

    return mutate


def drop_root_settings(spec):
    del spec["securityContext"]["runAsNonRoot"]
    del spec["securityContext"]["runAsUser"]
    del container(spec)["securityContext"]["runAsNonRoot"]


def drop_service_account(spec):
    del spec["serviceAccountName"]


def host_path_tmp(spec):
    spec["volumes"] = [{"name": "tmp", "hostPath": {"path": "/tmp", "type": "Directory"}}]


def declare_port(port):
    def mutate(spec):
        container(spec)["ports"] = [{"containerPort": port, "protocol": "TCP"}]

    return mutate


def host_port(spec):
    container(spec)["ports"] = [{"containerPort": 8080, "hostPort": 18080, "protocol": "TCP"}]


def toleration(spec):
    spec["tolerations"] = [{"key": "example.com/smoke", "operator": "Exists", "effect": "NoSchedule"}]


def no_logs(spec):
    container(spec)["command"] = ["sleep", "infinity"]


def drop_runtime_class(spec):
    del spec["runtimeClassName"]


def readiness_exec(period):
    def mutate(spec):
        container(spec)["readinessProbe"] = exec_probe(period)

    return mutate


def share_process_namespace(spec):
    spec["shareProcessNamespace"] = True


# test ID -> (workload name, mutation[, base]). Base "cpu" starts from the
# Guaranteed whole-CPU variant. bad-bare-pod is a bare Pod and bad-nodeport a
# Service, so their mutation is None.
POD_SPEC_VIOLATIONS = {
    "access-control-pod-host-network": ("bad-host-network", set_pod("hostNetwork", True)),
    "access-control-pod-host-pid": ("bad-host-pid", set_pod("hostPID", True)),
    "access-control-pod-host-ipc": ("bad-host-ipc", set_pod("hostIPC", True)),
    "access-control-pod-host-path": ("bad-host-path", host_path_tmp),
    "access-control-container-host-port": ("bad-host-port", host_port),
    "access-control-no-1337-uid": ("bad-uid-1337", lambda spec: spec["securityContext"].update(runAsUser=1337)),
    "access-control-security-context-privilege-escalation": ("bad-priv-esc", set_container_security("allowPrivilegeEscalation", True)),
    "access-control-security-context-read-only-root-file-system": ("bad-rw-root", set_container_security("readOnlyRootFilesystem", False)),
    "access-control-net-raw-capability-check": ("bad-net-raw", add_capability("NET_RAW")),
    "access-control-bpf-capability-check": ("bad-bpf", add_capability("BPF")),
    "access-control-ipc-lock-capability-check": ("bad-ipc-lock", add_capability("IPC_LOCK")),
    "access-control-net-admin-capability-check": ("bad-net-admin", add_capability("NET_ADMIN")),
    "access-control-sys-admin-capability-check": ("bad-sys-admin", add_capability("SYS_ADMIN")),
    "access-control-dac-override-capability-check": ("bad-dac-override", add_capability("DAC_OVERRIDE")),
    "access-control-dac-read-search-capability-check": ("bad-dac-read-search", add_capability("DAC_READ_SEARCH")),
    "access-control-sys-module-capability-check": ("bad-sys-module", add_capability("SYS_MODULE")),
    "access-control-requests": ("bad-no-requests", drop_container("resources")),
    "access-control-security-context-non-root-user-id-check": ("bad-root-user", drop_root_settings),
    "access-control-pod-service-account": ("bad-default-sa", drop_service_account),
    "access-control-sys-ptrace-capability": ("bad-ptrace", share_process_namespace),
    "lifecycle-image-pull-policy": ("bad-pull-always", set_container("imagePullPolicy", "Always")),
    "lifecycle-container-prestop": ("bad-no-prestop", drop_lifecycle("preStop")),
    "lifecycle-container-poststart": ("bad-no-poststart", drop_lifecycle("postStart")),
    "lifecycle-pod-owner-type": ("bad-bare-pod", None),
    "lifecycle-pod-toleration-bypass": ("bad-toleration", toleration),
    "lifecycle-pod-scheduling": ("bad-node-selector", set_pod("nodeSelector", {"kubernetes.io/os": "linux"})),
    "lifecycle-cpu-isolation": ("bad-cpu-isolation", drop_runtime_class, "cpu"),
    "observability-termination-policy": ("bad-termination-file", set_container("terminationMessagePolicy", "File")),
    "observability-container-logging": ("bad-no-logs", no_logs),
    "networking-reserved-partner-ports": ("bad-partner-port", declare_port(15000)),
    "networking-ocp-reserved-ports-usage": ("bad-ocp-port", declare_port(22623)),
    "performance-max-resources-exec-probes": ("bad-exec-probe-period", readiness_exec(5)),
    # A 10s period keeps this probe compliant for max-resources-exec-probes.
    "performance-cpu-pinning-no-exec-probes": ("bad-cpu-pinning", readiness_exec(10), "cpu"),
    "access-control-service-type": ("bad-nodeport", None),
}

def pod_spec_workload(name, mutation, base=None):
    spec = golden_pod_spec()
    annotations = None
    if base == "cpu":
        cpu_pinned(spec)
        annotations = CPU_PINNED_ANNOTATIONS
    if mutation:
        mutation(spec)
    return deployment(name, POD_SPEC_LABEL, spec, annotations=annotations)


def pod_spec_manifests():
    golden_spec = golden_pod_spec()
    cpu_spec = golden_pod_spec()
    cpu_pinned(cpu_spec)
    golden = [
        service_account(),
        deployment("golden", POD_SPEC_LABEL, golden_spec),
        deployment("good-cpu-pinned", POD_SPEC_LABEL, cpu_spec, annotations=CPU_PINNED_ANNOTATIONS),
        service("golden", "golden"),
    ]

    violations = [service_account()]
    for name, mutation, *base in POD_SPEC_VIOLATIONS.values():
        if name == "bad-bare-pod":
            violations.append(bare_pod(name, POD_SPEC_LABEL, golden_pod_spec()))
        elif name == "bad-nodeport":
            violations.append(service(name, name, "NodePort"))
        else:
            violations.append(pod_spec_workload(name, mutation, *base))

    no_fs_group = golden_pod_spec()
    del no_fs_group["securityContext"]["fsGroup"]
    security_context = [service_account(), deployment("bad-security-context", POD_SPEC_LABEL, no_fs_group)]

    ptrace_spec = golden_pod_spec()
    share_process_namespace(ptrace_spec)
    container(ptrace_spec)["securityContext"]["capabilities"]["add"] = ["SYS_PTRACE"]
    ptrace = [service_account(), deployment("good-ptrace", POD_SPEC_LABEL, ptrace_spec)]

    return {
        "pod-spec/manifests/golden.yaml": golden,
        "pod-spec/manifests/violations.yaml": violations,
        "pod-spec/manifests/bad-security-context.yaml": security_context,
        "pod-spec/manifests/ptrace.yaml": ptrace,
        "pod-spec/manifests/runtimeclass.yaml": [runtime_class()],
    }


# ---------------------------------------------------------------------------
# workload-controllers batch: HA, PDB, topology spread, affinity-required

CONTROLLERS_LABEL = "scenario-controllers"


def anti_affinity(name):
    return {
        "podAntiAffinity": {
            "requiredDuringSchedulingIgnoredDuringExecution": [
                {"labelSelector": {"matchLabels": {"app": name}}, "topologyKey": "kubernetes.io/hostname"}
            ]
        }
    }


def spread(name, keys):
    return [
        {
            "maxSkew": 1,
            "topologyKey": key,
            "whenUnsatisfiable": "ScheduleAnyway",
            "labelSelector": {"matchLabels": {"app": name}},
        }
        for key in keys
    ]


def controller(name, replicas=2, with_pdb=True, affinity="anti", tsc=None, affinity_required=False):
    spec = golden_pod_spec()
    if affinity == "anti":
        spec["affinity"] = anti_affinity(name)
    elif affinity == "node":
        spec["affinity"] = {
            "nodeAffinity": {
                "preferredDuringSchedulingIgnoredDuringExecution": [
                    {
                        "weight": 1,
                        "preference": {
                            "matchExpressions": [{"key": "kubernetes.io/os", "operator": "In", "values": ["linux"]}]
                        },
                    }
                ]
            }
        }
    if tsc:
        spec["topologySpreadConstraints"] = spread(name, tsc)
    extra = {"AffinityRequired": "true"} if affinity_required else None
    objects = [deployment(name, CONTROLLERS_LABEL, spec, replicas=replicas, extra_labels=extra)]
    if with_pdb:
        objects.append(pdb(name))
    return objects


CONTROLLER_VIOLATIONS = {
    "lifecycle-pod-high-availability": "bad-ha",
    "observability-pod-disruption-budget": "bad-pdb",
    "lifecycle-topology-spread-constraint": "bad-tsc",
    "lifecycle-affinity-required-pods": "bad-affinity-required",
}


def controller_manifests():
    golden = [service_account()]
    golden += controller("golden-ha")
    golden += controller("good-tsc", tsc=("kubernetes.io/hostname", "topology.kubernetes.io/zone"))
    golden += controller("good-affinity-required", affinity="node", affinity_required=True)

    violations = [service_account()]
    violations += controller("bad-ha", replicas=1)
    violations += controller("bad-pdb", with_pdb=False)
    violations += controller("bad-tsc", tsc=("kubernetes.io/hostname",))
    violations += controller("bad-affinity-required", affinity_required=True)
    return {
        "workload-controllers/manifests/golden.yaml": golden,
        "workload-controllers/manifests/violations.yaml": violations,
    }


# ---------------------------------------------------------------------------
# Minimal YAML emitter (stdlib only)

PLAIN = re.compile(r"^[A-Za-z_/][A-Za-z0-9_./-]*$")
AMBIGUOUS = {"true", "false", "yes", "no", "on", "off", "null", "y", "n"}


def scalar(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if PLAIN.match(value) and value.lower() not in AMBIGUOUS:
        return value
    return json.dumps(value)


def emit(value, indent=0):
    pad = " " * indent
    lines = []
    if isinstance(value, dict):
        if not value:
            return [pad + "{}"]
        for key, item in value.items():
            if isinstance(item, (dict, list)) and item:
                lines.append(f"{pad}{key}:")
                lines.extend(emit(item, indent + 2))
            elif isinstance(item, dict):
                lines.append(f"{pad}{key}: {{}}")
            elif isinstance(item, list):
                lines.append(f"{pad}{key}: []")
            else:
                lines.append(f"{pad}{key}: {scalar(item)}")
    else:
        for item in value:
            if isinstance(item, dict) and item:
                nested = emit(item, indent + 2)
                lines.append(f"{pad}- {nested[0].lstrip()}")
                lines.extend(nested[1:])
            elif isinstance(item, list) and item:
                raise ValueError("nested lists are not supported")
            else:
                lines.append(f"{pad}- {scalar(item)}")
    return lines


def render(objects):
    body = []
    for obj in objects:
        body.append("---")
        body.extend(emit(obj))
    return HEADER + "\n".join(body) + "\n"


def all_manifests():
    manifests = {}
    manifests.update(pod_spec_manifests())
    manifests.update(controller_manifests())
    return {path: render(objects) for path, objects in manifests.items()}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if a generated manifest is stale")
    args = parser.parse_args()

    stale = []
    for relative, content in all_manifests().items():
        path = SCRIPT_DIR / relative
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                stale.append(str(path.relative_to(ROOT)))
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"Wrote {path.relative_to(ROOT)}")

    if stale:
        print("Batch manifests are stale. Run python3 .github/actions/test-scenarios/batches/generate-manifests.py:", file=sys.stderr)
        for path in stale:
            print(f"  {path}", file=sys.stderr)
        return 1
    if args.check:
        print("Batch manifests are up to date.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
